      const pushed = values.slice(0, i + 1);
      const stored = pushed.slice(-LENGTH);
      const dropped = pushed.slice(0, -LENGTH);

      // check count
      expect(await this.mock.$length(0)).to.equal(LENGTH);
      expect(await this.mock.$count(0)).to.equal(stored.length);

